// n8n Code node: "Build Discord message" (workflows/job-tracker.json)
// Generated by scripts/export-code.js. Edit the workflow, not this file.

// Formats the Discord message.
const d = $('Decide').first().json;
const pageUrl = $json.url || d.pageUrl || '';
const gmailUrl = `https://mail.google.com/mail/u/0/#all/${d.threadId}`;

const STYLE = {
  application_confirmation: { emoji: '📝', label: 'Application logged', color: 3447003 },
  rejection:        { emoji: '❌', label: 'Rejection',          color: 15158332 },
  interview_invite: { emoji: '🎉', label: 'Interview invite',   color: 3066993 },
  assessment:       { emoji: '🧩', label: 'Assessment',         color: 15105570 },
  offer:            { emoji: '🏆', label: 'OFFER',              color: 15844367 },
  info_request:     { emoji: '📨', label: 'Info requested',     color: 3447003 },
  status_update:    { emoji: '🔄', label: 'Status update',      color: 9807270 },
  recruiter_outreach: { emoji: '👋', label: 'Recruiter outreach', color: 10181046 },
};
const st = STYLE[d.type] || { emoji: '📬', label: 'Update', color: 9807270 };
const links = [`[Open email](${gmailUrl})`, pageUrl ? `[Notion](${pageUrl})` : ''].filter(Boolean).join(' · ');

let body;
if (d.type === 'application_confirmation') {
  body = { content: `${st.emoji} Logged new application: **${d.role || 'role unknown'}** at **${d.company || 'unknown company'}** · ${links}` };
} else {
  const fields = [
    { name: 'Role', value: d.role, inline: true },
    { name: 'Status', value: d.status, inline: true },
    { name: 'Next action', value: d.nextAction, inline: false },
    { name: 'Deadline', value: d.deadline, inline: true },
    { name: 'Links', value: links, inline: false },
  ].filter(f => f.value).map(f => ({ ...f, value: String(f.value).slice(0, 1000) }));
  body = {
    embeds: [{
      title: `${st.emoji} ${st.label}: ${d.company || 'Unknown company'}`.slice(0, 250),
      description: (d.summary || '').slice(0, 2000),
      color: st.color,
      fields,
      footer: { text: `${d.fromAddress} · ${d.subject}`.slice(0, 2000) },
      timestamp: new Date().toISOString(),
    }],
  };
}
return [{ json: { discordBody: body } }];
